  mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0;S0] [S0] 1 0 []))
          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1] [S0] 1 0 [])) 0 4.
