Definition mk_1RB0RD_1LC0LB_1LD0LB_1RD0RA (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB0RD_1LC0LB_1LD0LB_1RD0RA.

(** 1RB0RD_1LC0LB_1LD0LB_1RD0RA *)
Definition tm_1RB0RD_1LC0LB_1LD0LB_1RD0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S0 DR StD
  | StB, S0 => mk S1 DL StC
  | StB, S1 => mk S0 DL StB
  | StC, S0 => mk S1 DL StD
  | StC, S1 => mk S0 DL StB
  | StD, S0 => mk S1 DR StD
  | StD, S1 => mk S0 DR StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB0RD_1LC0LB_1LD0LB_1RD0RA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB0RD_1LC0LB_1LD0LB_1RD0RA pins_1RB0RD_1LC0LB_1LD0LB_1RD0RA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB0RD_1LC0LB_1LD0LB_1RD0RA : Fam := mkFam 2 [[S0;S0];[S0;S1]] [S1] [[]] Gray 2 [mkFill 1 [] 0 [1;1] 0] StC S0 false [S1].
Local Notation FAM := fam_1RB0RD_1LC0LB_1LD0LB_1RD0RA.

(** ** The ladder, as DATA

    2 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB0RD_1LC0LB_1LD0LB_1RD0RA : list (LRule * list rstep) :=
  [(mkLRule (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S0] [] 0 0 [])) (mkC StD (mkS [S1] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 1, [RB (SWin 1)]);
   (mkLRule (mkC StB (mkS [S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0] [] 0 0 [])) 0 1, [RB (SWin 1)])].
Local Notation lad := lad_1RB0RD_1LC0LB_1LD0LB_1RD0RA.

Definition rules_1RB0RD_1LC0LB_1LD0LB_1RD0RA : list LRule := map fst lad.
Local Notation rules := rules_1RB0RD_1LC0LB_1LD0LB_1RD0RA.

Lemma ladder_ok_1RB0RD_1LC0LB_1LD0LB_1RD0RA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB0RD_1LC0LB_1LD0LB_1RD0RA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB0RD_1LC0LB_1LD0LB_1RD0RA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
