(** The machine-level theorem, at the INSTRUCTION level
    ([LadderCheckGrayTr.boardG_neverqhtr]). *)
Theorem nqhtr_1RB0RD_1LC0LB_1LD0LB_1RD0RA : NeverQuasiHaltsTr tm_1RB0RD_1LC0LB_1LD0LB_1RD0RA.
Proof.
  eapply (boardG_neverqhtr tm_1RB0RD_1LC0LB_1LD0LB_1RD0RA pins_1RB0RD_1LC0LB_1LD0LB_1RD0RA FAM 0
    iarm_1RB0RD_1LC0LB_1LD0LB_1RD0RA 0 1 farm_1RB0RD_1LC0LB_1LD0LB_1RD0RA 2 1 fw1_1RB0RD_1LC0LB_1LD0LB_1RD0RA fw2_1RB0RD_1LC0LB_1LD0LB_1RD0RA fm1_1RB0RD_1LC0LB_1LD0LB_1RD0RA fm2_1RB0RD_1LC0LB_1LD0LB_1RD0RA
    vis_1RB0RD_1LC0LB_1LD0LB_1RD0RA [1;1]).
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
