  mkLRule (mkC StC (mkS [S1] [] 0 0 []) S0 (mkS [S1;S0;S0;S0;S0] [S0;S0] 1 0 []))
          (mkC StC (mkS [S1] [] 0 0 []) S0 (mkS [S1;S0;S1;S0;S1] [S0;S0] 1 0 [])) 0 20.
