(** The machine-level theorem, at the INSTRUCTION level
    ([LadderCheckGrayTr.boardG_neverqhtr]). *)
Theorem nqhtr_1RB1LC_0LA0RB_0LD1LD_1RA0RA : NeverQuasiHaltsTr tm_1RB1LC_0LA0RB_0LD1LD_1RA0RA.
Proof.
  eapply (boardG_neverqhtr tm_1RB1LC_0LA0RB_0LD1LD_1RA0RA pins_1RB1LC_0LA0RB_0LD1LD_1RA0RA FAM 0
    iarm_1RB1LC_0LA0RB_0LD1LD_1RA0RA 0 1 farm_1RB1LC_0LA0RB_0LD1LD_1RA0RA 2 1 fw1_1RB1LC_0LA0RB_0LD1LD_1RA0RA fw2_1RB1LC_0LA0RB_0LD1LD_1RA0RA fm1_1RB1LC_0LA0RB_0LD1LD_1RA0RA fm2_1RB1LC_0LA0RB_0LD1LD_1RA0RA
    vis_1RB1LC_0LA0RB_0LD1LD_1RA0RA [1;1]).
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - vm_compute; reflexivity.
  - lia.
  - vm_compute; repeat constructor.
  - vm_compute; repeat constructor.
  - vm_compute; lia.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - intros k Hk.
    rewrite (filled_parity FAM 0 k ltac:(vm_compute; reflexivity)).
    vm_compute; reflexivity.
  - repeat constructor.
  - vm_compute; lia.
  - vm_compute; reflexivity.
  - lia.
  - exact iarm_sound_1RB1LC_0LA0RB_0LD1LD_1RA0RA.
  - exact iarm_lhs_1RB1LC_0LA0RB_0LD1LD_1RA0RA.
  - exact iarm_rhs_1RB1LC_0LA0RB_0LD1LD_1RA0RA.
